'use client';

import { forwardRef, type ButtonHTMLAttributes } from 'react';
import './shutter-button.css';

export interface ShutterButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {}

/** A native button with opposing diagonal shutters and a rotating plus. */
export const ShutterButton = forwardRef<HTMLButtonElement, ShutterButtonProps>(
  function ShutterButton({ children, className = '', type = 'button', ...props }, ref) {
    return (
      <button
        {...props}
        ref={ref}
        type={type}
        className={`ac-shutter-button ${className}`.trim()}
      >
        <span className="ac-shutter-button__surface">
          <span className="ac-shutter-button__label">{children}</span>
          <svg
            className="ac-shutter-button__plus"
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            aria-hidden="true"
            focusable="false"
          >
            <path d="M5 12h14M12 5v14" stroke="currentColor" strokeWidth="1.6" />
          </svg>
        </span>
      </button>
    );
  },
);

export default ShutterButton;

.ac-shutter-button,
.ac-shutter-button::before,
.ac-shutter-button::after,
.ac-shutter-button *,
.ac-shutter-button *::before,
.ac-shutter-button *::after {
  box-sizing: border-box;
}

.ac-shutter-button {
  --ac-shutter-focus: #e45534;

  position: relative;
  display: inline-flex;
  min-height: 48px;
  max-width: 100%;
  padding: 0;
  border: 1px solid var(--ac-shutter-border, var(--ac-shutter-button-theme-line, #c9c9be));
  border-radius: 6px;
  background: var(--ac-shutter-background, var(--ac-shutter-button-theme-paper, #e9e8df));
  color: var(--ac-shutter-foreground, var(--ac-shutter-button-theme-ink, #24251f));
  font: inherit;
  font-weight: 500;
  line-height: 1.2;
  text-align: center;
  vertical-align: middle;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.ac-shutter-button__surface {
  position: relative;
  isolation: isolate;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  gap: 2.25em;
  min-width: 0;
  min-height: inherit;
  overflow: hidden;
  padding: 0.9em 1.2em;
  border-radius: inherit;
}

.ac-shutter-button__surface::before,
.ac-shutter-button__surface::after {
  position: absolute;
  z-index: -1;
  inset: -1px;
  background: var(--ac-shutter-panel, var(--ac-shutter-button-theme-ink, #24251f));
  transition: transform 480ms cubic-bezier(0.16, 1, 0.3, 1);
  content: '';
}

.ac-shutter-button__surface::before {
  clip-path: polygon(0 0, 100% 0, 100% 2%, 0 100%);
  transform: translate(-101%, -101%);
}

.ac-shutter-button__surface::after {
  clip-path: polygon(100% 0, 100% 100%, 0 100%);
  transform: translate(101%, 101%);
}

.ac-shutter-button__label,
.ac-shutter-button__plus {
  position: relative;
  transition: color 150ms ease 60ms, transform 400ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ac-shutter-button__label {
  min-width: 0;
  overflow-wrap: anywhere;
}

.ac-shutter-button__plus {
  flex: 0 0 auto;
}

.ac-shutter-button:not(:disabled):is(:hover, :focus-visible, :active)
  .ac-shutter-button__surface::before,
.ac-shutter-button:not(:disabled):is(:hover, :focus-visible, :active)
  .ac-shutter-button__surface::after {
  transform: translate(0, 0);
}

.ac-shutter-button:not(:disabled):is(:hover, :focus-visible, :active)
  :is(.ac-shutter-button__label, .ac-shutter-button__plus) {
  color: var(--ac-shutter-active-foreground, var(--ac-shutter-button-theme-active-ink, #f6f5ef));
}

.ac-shutter-button:not(:disabled):is(:hover, :focus-visible, :active)
  .ac-shutter-button__plus {
  transform: rotate(45deg);
}

.ac-shutter-button:not(:disabled):active .ac-shutter-button__plus {
  transform: rotate(45deg) scale(0.85);
}

.ac-shutter-button:focus-visible {
  outline: 2px solid var(--ac-shutter-focus);
  outline-offset: 4px;
}

.ac-shutter-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

@media (hover: none) {
  .ac-shutter-button:not(:disabled):hover:not(:active):not(:focus-visible)
    .ac-shutter-button__surface::before {
    transform: translate(-101%, -101%);
  }

  .ac-shutter-button:not(:disabled):hover:not(:active):not(:focus-visible)
    .ac-shutter-button__surface::after {
    transform: translate(101%, 101%);
  }

  .ac-shutter-button:not(:disabled):hover:not(:active):not(:focus-visible)
    :is(.ac-shutter-button__label, .ac-shutter-button__plus) {
    color: var(--ac-shutter-foreground, var(--ac-shutter-button-theme-ink, #24251f));
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ac-shutter-button__surface::before,
  .ac-shutter-button__surface::after,
  .ac-shutter-button__label,
  .ac-shutter-button__plus {
    transition: none;
  }

  .ac-shutter-button .ac-shutter-button__plus {
    transform: none !important;
  }
}

/* Neutral defaults follow the page theme; explicit component colors keep priority. */
:where([data-theme="light"], .light) .ac-shutter-button {
  --ac-shutter-button-theme-paper: #f3f4ef;
  --ac-shutter-button-theme-ink: #24251f;
  --ac-shutter-button-theme-active-ink: #f6f5ef;
  --ac-shutter-button-theme-line: #c9c9be;
}
:where([data-theme="dark"], .dark) .ac-shutter-button {
  --ac-shutter-button-theme-paper: #262c23;
  --ac-shutter-button-theme-ink: #e4eadb;
  --ac-shutter-button-theme-active-ink: #242a21;
  --ac-shutter-button-theme-line: #5e6756;
}
